localdir = os.path.dirname(os.path.abspath(__file__))

# Base parameters, as required by every PocketCoffea config
parameters = defaults.merge_parameters_from_files(
    defaults.get_default_parameters(),
    update=True,
)

# --- Jet multiplicity binning: exactly 4, exactly 5, >= 6 "JetGood" jets ---
njet_binning = MultiCut(
    name="njet",
    cuts=[
        get_nObj_eq(4, coll="JetGood", name="4jets"),
        get_nObj_eq(5, coll="JetGood", name="5jets"),
        get_nObj_min(6, coll="JetGood", name="6jets"),
